{
  "name": "@macqueen1001/opencode-think-with-me",
  "version": "0.1.0",
  "description": "opencode plugin and skill for long-running think-with-me sessions: a thinking partner that keeps a durable state.md per topic across conversations.",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "skill"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/macqueen01/think-with-me.git",
    "directory": "plugin"
  },
  "type": "module",
  "main": "./dist/think-with-me.js",
  "exports": {
    ".": "./dist/think-with-me.js",
    "./server": "./dist/think-with-me.js"
  },
  "files": [
    "dist",
    "skills"
  ],
  "engines": {
    "opencode": ">=1.18.0"
  },
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "build": "bun build ./think-with-me.ts --target=node --format=esm --outdir=dist",
    "skills": "rm -rf ./skills && mkdir -p ./skills && cp -R ../think-with-me ./skills/think-with-me",
    "prepack": "bun run skills && bun run build",
    "test": "bun test"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "1.4.10",
    "@types/bun": "^1.3.9"
  }
}
